const m = $json.metals || {};
let g24 = Number(m.gold||0); // ₹ per gram if unit=g & currency=INR
if (!g24 && $json.rates?.XAU) g24 = Number($json.rates.XAU)/31.1035; // fallback per-oz shape
if (!g24) throw new Error('No gold rate in response — check provider/plan');
const prem = 1 + Number($env.LOCAL_PREMIUM_PCT||2)/100;
const r24 = Math.round(g24*prem), r22 = Math.round(r24*0.916), ag = Math.round(Number(m.silver||0)*prem);
return [{ json: { Date: new Date().toISOString().slice(0,10), Rate24K: r24, Rate22K: r22, RateSilver: ag||'' } }];

const t=new Date().toISOString().slice(0,10);
const ff=items.map(i=>i.json).filter(r=>r.Date===t).length;
return [{ json: { text: `🚶 Footfall today: ${ff} visitors. Compare with today's enquiries & bills to see conversion — if footfall is high but sales low, review counter experience & staff scripts.` } }];

const wk=new Date(Date.now()-7*864e5).toISOString();
const agg={};
items.map(i=>i.json).filter(r=>r.Time>=wk).forEach(r=>{agg[r.Design]=agg[r.Design]||{t:0,e:0};agg[r.Design].t++;if(r.Action==='enquire')agg[r.Design].e++});
const top=Object.entries(agg).sort((a,b)=>b[1].t-a[1].t).slice(0,8);
return [{ json: { text: top.length? '💎 Most-tried designs this week (try-ons → enquiries):\n'+top.map(([d,v],i)=>`${i+1}. ${d} — ${v.t} try-ons, ${v.e} enquiries`).join('\n')+'\n\n➡ Stock & post more of the top 3.' : 'No try-on events this week.' } }];
